PROVENANCE_TAG = "UMLS-Full 2025AA"

def apply():
    """Mutate the imported ontology dicts in-place with UMLS enrichment."""
    from rules.epilepsy_ontology import (
        all_enum_ontologies, supplementary_ontologies,
    )
    all_maps = {**all_enum_ontologies(), **supplementary_ontologies()}
    for group_name, updates in UMLS_OVERRIDES.items():
        onto = all_maps.get(group_name)
        if not onto:
            continue
        for value_key, patch in updates.items():
            entry = onto.get(value_key)
            if not entry:
                continue
            existing = {s.lower().strip() for s in entry.synonyms}
            for syn in patch.get("add_synonyms", []):
                if syn.lower().strip() not in existing:
                    entry.synonyms.append(syn)
                    existing.add(syn.lower().strip())
            sct = patch.get("set_sctid")
            if sct and not entry.sctid:
                entry.sctid = sct
            if PROVENANCE_TAG not in entry.source_provenance:
                entry.source_provenance.append(PROVENANCE_TAG)
